char *fio_option_dup_subs(const char *opt)
{
        char out[OPT_LEN_MAX+1];
        char in[OPT_LEN_MAX+1];
        char *outptr = out;
        char *inptr = in;
        char *ch1, *ch2, *env;
        ssize_t nchr = OPT_LEN_MAX;
        size_t envlen;

        if (strlen(opt) + 1 > OPT_LEN_MAX) {
                log_err("OPT_LEN_MAX (%d) is too small\n", OPT_LEN_MAX);
                return NULL;
        }

        snprintf(in, sizeof(in), "%s", opt);

        while (*inptr && nchr > 0) {
                if (inptr[0] == '$' && inptr[1] == '{') {
                        ch2 = strchr(inptr, '}');
                        if (ch2 && inptr+1 < ch2) {
                                ch1 = inptr+2;
                                inptr = ch2+1;
                                *ch2 = '\0';

                                env = getenv(ch1);
                                if (env) {
                                        envlen = strlen(env);
                                        if (envlen <= nchr) {
                                                memcpy(outptr, env, envlen);
                                                outptr += envlen;
                                                nchr -= envlen;
                                        }
                                }

                                continue;
                        }
                }

                *outptr++ = *inptr++;
                --nchr;
        }

        *outptr = '\0';
        return strdup(out);
}

